'use strict';
const Studio=(()=>{
 const esc=senEscape,stages=['Explore together','Practise with support','Try new examples','Use and revisit'];let token=0,timer=null;
 const old={title:skillTitle,art:skillArt,launch:skillLaunch,course:skillCourse,nav:skillNav,restore:skillRestoreRoute};
 const registry=()=>learningSkills.flatMap(s=>s.courses.map(c=>({...c,skillId:s.id,skillTitle:s.title})));
 for(const c of studioPilots){for(const a of c.activities){if(a.key==='build-word')a.key=readingGames.find(g=>g.mode==='spell').id;if(a.engine==='vocabulary'&&!vocabularyCategories.has(a.category))throw Error('Unknown pilot vocabulary category: '+a.category);}skillGet(c.skill).courses.push(c);}
 function go(hash){readingCancel();token++;clearTimeout(timer);if(location.hash!==hash)history.pushState(null,'',location.pathname+hash);route();}
 function nav(){old.nav();let n=document.getElementById('studioNav');if(!n){n=document.createElement('nav');n.id='studioNav';n.setAttribute('aria-label','Main navigation');document.querySelector('header').append(n);}n.innerHTML=[['support','Find support'],['courses','Courses'],['research','Research'],['practice','My practice']].map(([id,label])=>'<a href="#'+id+'">'+label+'</a>').join('');n.querySelectorAll('a').forEach(a=>{const active=location.hash.startsWith('#research')?'research':location.hash.startsWith('#practice')?'practice':/^#(?:course|activity)/.test(location.hash)?'courses':'support';if(a.getAttribute('href')==='#'+active)a.setAttribute('aria-current','page');a.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();go(a.getAttribute('href'));};});document.body.classList.add('studio');const brand=document.querySelector('#brand');if(!brand.dataset.studioBrand){brand.innerHTML='<span class="studio-brand-mark" aria-hidden="true"></span><span>Spot &amp; Match<small>Small steps. Shared discoveries.</small></span>';brand.dataset.studioBrand='true';}document.querySelector('#brand').onclick=e=>{e.preventDefault();go('#support');};}
 function heading(label,title,copy){return '<section class="studio-hero"><span class="eyebrow">'+label+'</span><h1>'+esc(title)+'</h1><p>'+esc(copy)+'</p></section>';}
 function bind(){nav();app.querySelectorAll('[data-studio-activity]').forEach(a=>a.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();const[id,index]=a.dataset.studioActivity.split(':');skillLaunch(id,+index);});app.querySelectorAll('[data-studio-course]').forEach(a=>a.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();skillCourse(a.dataset.studioCourse);});app.querySelectorAll('[data-studio-go]').forEach(a=>a.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();go(a.getAttribute('href'));});}
 function card(c){return StudioDesign.card(c,{esc,art:skillArt});}
 function courses(){skillContext=null;const p=new URLSearchParams(location.hash.split('?')[1]||''),query=p.get('q')||'',skill=p.get('skill')||'';app.innerHTML=heading('COURSES','Choose a useful learning goal','Short sessions, clear purposes and support you can adapt.')+'<form id="studioSearch" role="search"><label>Search courses<input value="'+esc(query)+'" placeholder="Words, attention or communication"></label><label>Skill<select><option value="">All skills</option>'+learningSkills.map(s=>'<option value="'+s.id+'" '+(skill===s.id?'selected':'')+'>'+esc(s.title)+'</option>').join('')+'</select></label><button class="primary">Find courses</button></form><p id="studioCount" role="status"></p><div class="studio-grid" id="studioResults"></div>';const found=registry().filter(c=>(!skill||c.skillId===skill)&&StudioDesign.courseMatches(c,query)).sort((a,b)=>Number(!!b.pilot)-Number(!!a.pilot));app.querySelector('#studioCount').textContent=found.length+' courses';app.querySelector('#studioResults').innerHTML=found.map(card).join('')||'<p>No courses match. Try another word or all skills.</p>';app.querySelector('form').onsubmit=e=>{e.preventDefault();go('#courses?q='+encodeURIComponent(app.querySelector('input').value)+'&skill='+encodeURIComponent(app.querySelector('select').value));};bind();}
 function practice(){skillContext=null;let recent=null;try{recent=JSON.parse(localStorage.getItem('spotmatch-last-course-v1')||'null');}catch{}app.innerHTML=heading('MY PRACTICE','Return to a useful activity','Notes stay in this browser. Explored activities are not mastery scores.')+'<div class="studio-grid">'+(registry().filter(c=>skillNotes[c.id]||recent?.courseId===c.id).map(card).join('')||'<p>Start a course. Explored activities will appear here.</p>')+'</div><button id="studioExport" class="secondary">Export local practice</button><label>Import practice file<input id="studioImport" type="file" accept="application/json"></label><p id="studioImportStatus" role="status"></p>';app.querySelector('#studioExport').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(StudioCore.pack(skillNotes,registry()))],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='spot-match-practice.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};app.querySelector('#studioImport').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>1000000)throw Error('Choose a practice file below 1 MB.');const data=JSON.parse(await file.text());const result=StudioCore.unpack(data,registry(),skillNotes);localStorage.setItem('spotmatch-practice-backup-v1',JSON.stringify(skillNotes));localStorage.setItem('spotmatch-course-notes-v1',JSON.stringify(result.notes));skillNotes=result.notes;app.querySelector('#studioImportStatus').textContent='Practice merged; existing notes were backed up in this browser.'+(result.skipped?' '+result.skipped+' course versions did not match and were left unchanged.':'');}catch(error){app.querySelector('#studioImportStatus').textContent=error.message;}};bind();}
 function research(){skillContext=null;StudioResearchView.render({app,esc,data:studioResearch,heading,bind,go,sources:readingSources});}
 function support(){StudioDesign.home({app,esc,registry,bind,go});}
 const supportDetail=parentSupportDetail;parentSupportDetail=id=>{supportDetail(id);const head=app.querySelector('.support-detail-head');if(!head)return;const research=app.querySelector('.parent-research');if(research)research.id='studioSupportResearch';const jump=document.createElement('nav');jump.className='studio-support-jump';jump.setAttribute('aria-label','On this support page');jump.innerHTML='<a href="#supportGames">Try a game</a><a href="#supportCourses">Find a course</a><a href="#studioSupportResearch">Research & adaptations</a>';head.after(jump);jump.querySelectorAll('a').forEach(a=>a.onclick=e=>{e.preventDefault();const target=app.querySelector(a.getAttribute('href'));if(target){if(target.tagName==='DETAILS')target.open=true;target.setAttribute('tabindex','-1');target.scrollIntoView({block:'start'});target.focus({preventScroll:true});}});};
 skillHome=()=>{skillWriteRoute('skills');support();};
 skillTitle=a=>a.engine==='offline'?a.title:a.title||old.title(a);skillArt=a=>a.engine==='offline'?readingPicture('bag'):old.art(a);skillNav=nav;
 skillCourse=id=>{token++;clearTimeout(timer);old.course(id);const c=skillCourseGet(id).course;if(c.pilot){const section=app.querySelector('.skill-course-activities');section.innerHTML='<p class="studio-notice">Curriculum draft · Educator review pending. Adult support is needed. Try one to three activities for a short visit.</p><p><b>Start with:</b> '+esc(c.entry)+'</p>'+StudioDesign.stages(c,esc);section.querySelectorAll('button').forEach(b=>b.onclick=()=>skillLaunch(id,+b.dataset.pilotActivity));}StudioDesign.polishCourse(c,esc);bind();};
 function offline(id,index){const c=skillCourseGet(id).course,a=c.activities[index],instance=++token;let paused=false,completed=false,pending=null;skillContext={skillId:c.skill,courseId:id,index};skillWriteRoute('activity',id,index);const render=()=>{app.innerHTML='<section class="studio-offline"><button id="studioBack" class="back">← Back to course</button><span>'+(index+1)+' / 16 · Together away from the screen</span><h1>'+esc(a.title)+'</h1><div class="studio-offline-art">'+readingPicture('bag')+readingPicture('cup')+'</div><h2>'+esc(a.invitation)+'</h2><p><b>We are practising:</b> '+esc(a.purpose)+'</p><p><b>Try it together:</b> '+esc(a.adultModel)+'</p><details><summary>Adapt it for this child</summary>'+a.adaptations.map(x=>'<p>'+esc(x)+'</p>').join('')+'</details><p>'+esc(a.transfer)+'</p><button id="studioPause" class="secondary">'+(paused?'Resume':'Pause')+'</button><button id="studioTried" class="primary" '+(paused||completed?'disabled':'')+'>We tried this together</button><p role="status">'+(paused?'Paused. Take your time.':'Shared practice, not a correct-answer score.')+'</p></section>';app.querySelector('#studioBack').onclick=()=>skillCourse(id);app.querySelector('#studioPause').onclick=()=>{paused=!paused;clearTimeout(timer);if(!paused&&completed&&CourseFlow.enabled&&pending)timer=setTimeout(pending,1100);render();if(completed&&!CourseFlow.enabled&&pending){const b=document.createElement('button');b.id='studioOfflineContinue';b.className='primary';b.textContent='Continue';b.disabled=paused;b.onclick=pending;app.append(b);}};app.querySelector('#studioTried').onclick=()=>{if(paused||completed||instance!==token)return;completed=true;skillNotes[id]??={};skillNotes[id].activities??={};skillNotes[id].activities[index]=true;skillSave();app.querySelector('#studioTried').disabled=true;app.querySelector('[role=status]').textContent='Thanks for exploring together.';const next=()=>{if(instance!==token)return;if(index+1<16)skillLaunch(id,index+1);else skillCourse(id);};pending=next;if(CourseFlow.enabled)timer=setTimeout(next,1100);else{const b=document.createElement('button');b.textContent='Continue';b.id='studioOfflineContinue';b.className='primary';b.onclick=next;app.append(b);}};nav();};render();}
 skillLaunch=(id,index)=>{const c=skillCourseGet(id).course,a=c.activities[index];token++;clearTimeout(timer);try{localStorage.setItem('spotmatch-last-course-v1',JSON.stringify({courseId:id,index}));}catch{}if(a.engine==='offline'){offline(id,index);return;}old.launch(id,index);if(c.pilot){const note=document.createElement('section');note.className='wq-support';note.id='studioPurpose';note.innerHTML='<h2>Why this activity?</h2><p>We are practising: '+esc(a.purpose)+'</p><p>May be useful when: '+esc(c.need)+'</p><details><summary>Adult model and adaptations</summary><p>'+esc(a.adultModel)+'</p>'+a.adaptations.map(x=>'<p>'+esc(x)+'</p>').join('')+'<p>This sequence has not been evaluated as an intervention.</p></details>';app.append(note);}nav();};
 const decorate=skillDecorate;skillDecorate=()=>{decorate();if(!skillContext||skillContext.index===null||app.querySelector('#studioPurpose'))return;const c=skillCourseGet(skillContext.courseId).course;if(!c.pilot||!app.querySelector('.reading-play,.vocabulary-play'))return;const a=c.activities[skillContext.index],n=document.createElement('section');n.id='studioPurpose';n.className='wq-support';n.innerHTML='<h2>Why this activity?</h2><p>'+esc(a.purpose)+'</p><details><summary>Model and adapt</summary><p>'+esc(a.adultModel)+'</p>'+a.adaptations.map(x=>'<p>'+esc(x)+'</p>').join('')+'</details>';app.append(n);};
 const renderVocabulary=vocabularyRender;vocabularyRender=()=>{renderVocabulary();if(!skillContext||skillContext.index===null)return;const c=skillCourseGet(skillContext.courseId).course,a=c.activities[skillContext.index];if(!c.pilot)return;const h=app.querySelector('.vocabulary-play h1'),e=app.querySelector('.vocabulary-play .eyebrow');if(h)h.textContent=a.title;if(e)e.textContent='Picture meanings · An adult joins in';};
 const startVocabulary=vocabularyStart;vocabularyStart=(...args)=>{startVocabulary(...args);const a=skillContext&&skillContext.index!==null?skillCourseGet(skillContext.courseId).course.activities[skillContext.index]:null;if(a?.id==='A05'){vocabularyState.groups=[{category:'004',label:'Animal hotel',ids:['puppy','kitten']},{category:'004',label:'Object store',ids:['cup','spoon']}];vocabularyState.sortCards=['cup','puppy','spoon','kitten'];vocabularyState.sorted={};vocabularyState.names=false;vocabularyRender();}if(a?.id==='A06'){vocabularyState.collected=vocabularyState.collection.slice(0,2);vocabularyState.names=false;vocabularyRender();}if(a?.id==='A10'){vocabularyState.collection=vocabularyState.collection.slice(0,2);vocabularyState.names=false;vocabularyRender();}};
 function route(){token++;clearTimeout(timer);readingCancel();const hash=location.hash;if(hash==='#support'||hash==='#skills'||!hash)support();else if(hash.startsWith('#courses'))courses();else if(hash.startsWith('#practice'))practice();else if(hash.startsWith('#research'))research();else{old.restore();nav();}}
 skillRestoreRoute=()=>{if(/^#(courses|research|practice)([/?]|$)/.test(location.hash)||location.hash==='#support'){route();return true;}return old.restore();};window.addEventListener('popstate',route);window.addEventListener('hashchange',route);nav();if(!location.hash||location.hash==='#skills'||location.hash==='#support')support();else route();return{registry,route,go};
})();
